import{_ as a,c as t,o as r,ag as l}from"./chunks/framework.CMajxlqO.js";const k=JSON.parse('{"title":"Lägg till enheter","description":"","frontmatter":{},"headers":[],"relativePath":"02-projektstruktur/lagg-till-enheter.md","filePath":"02-projektstruktur/lagg-till-enheter.md","lastUpdated":1768315788000}'),i={name:"02-projektstruktur/lagg-till-enheter.md"};function n(o,e,s,g,u,d){return r(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="lagg-till-enheter" tabindex="-1">Lägg till enheter <a class="header-anchor" href="#lagg-till-enheter" aria-label="Permalink to &quot;Lägg till enheter&quot;">​</a></h1><p>Efter att du skapat ett projekt behöver du lägga till hårdvara - PLC, HMI-panel och eventuellt frekvensomriktare. TIA Portal har en omfattande hårdvarukatalog där du väljer exakt de komponenter du ska använda i ditt projekt.</p><h2 id="oppna-hardvarukatalogen" tabindex="-1">Öppna hårdvarukatalogen <a class="header-anchor" href="#oppna-hardvarukatalogen" aria-label="Permalink to &quot;Öppna hårdvarukatalogen&quot;">​</a></h2><p>Det finns två sätt att komma åt hårdvarukatalogen:</p><h3 id="metod-1-via-project-view" tabindex="-1">Metod 1: Via Project View <a class="header-anchor" href="#metod-1-via-project-view" aria-label="Permalink to &quot;Metod 1: Via Project View&quot;">​</a></h3><ol><li>Öppna <strong>Project View</strong> (om du är i Portal View)</li><li>Dubbelklicka på &quot;Add new device&quot; i projektträdet</li><li>Hårdvarukatalogen öppnas</li></ol><h3 id="metod-2-via-network-view" tabindex="-1">Metod 2: Via Network View <a class="header-anchor" href="#metod-2-via-network-view" aria-label="Permalink to &quot;Metod 2: Via Network View&quot;">​</a></h3><ol><li>Dubbelklicka på &quot;Devices &amp; networks&quot; i projektträdet</li><li>Klicka på &quot;Add new device&quot; i verktygsfältet</li><li>Eller dra enheter direkt från katalogen (höger sida)</li></ol><h2 id="lagga-till-plc-s7-1200" tabindex="-1">Lägga till PLC (S7-1200) <a class="header-anchor" href="#lagga-till-plc-s7-1200" aria-label="Permalink to &quot;Lägga till PLC (S7-1200)&quot;">​</a></h2><h3 id="steg-1-valj-cpu" tabindex="-1">Steg 1: Välj CPU <a class="header-anchor" href="#steg-1-valj-cpu" aria-label="Permalink to &quot;Steg 1: Välj CPU&quot;">​</a></h3><ol><li>I hårdvarukatalogen, navigera till: <ul><li><strong>Controllers</strong> → <strong>SIMATIC S7-1200</strong> → <strong>CPU</strong></li></ul></li><li>Välj din CPU-modell (t.ex. &quot;CPU 1214C DC/DC/DC&quot;) <ul><li><strong>DC/DC/DC</strong> = 24V DC matning, 24V DC in/ut</li><li><strong>AC/DC/RLY</strong> = 230V AC matning, relay-utgångar</li></ul></li><li>Dra CPU:n till nätverksvyn eller dubbelklicka</li></ol><h3 id="steg-2-cpu-version-och-firmware" tabindex="-1">Steg 2: CPU-version och firmware <a class="header-anchor" href="#steg-2-cpu-version-och-firmware" aria-label="Permalink to &quot;Steg 2: CPU-version och firmware&quot;">​</a></h3><ul><li>Välj rätt firmware-version (helst senaste)</li><li>Om du har fysisk PLC: kontrollera vilken firmware den har</li><li>För simulering: välj senaste versionen</li></ul><h3 id="steg-3-namnge-plc-n" tabindex="-1">Steg 3: Namnge PLC:n <a class="header-anchor" href="#steg-3-namnge-plc-n" aria-label="Permalink to &quot;Steg 3: Namnge PLC:n&quot;">​</a></h3><ol><li>Klicka på PLC:n i nätverksvyn</li><li>I &quot;Properties&quot; längst ner, ändra namn till något beskrivande <ul><li>Exempel: <code>PLC_Main</code>, <code>Controller_Line1</code></li></ul></li><li>Tryck Enter för att bekräfta</li></ol><h3 id="steg-4-konfigurera-ip-adress" tabindex="-1">Steg 4: Konfigurera IP-adress <a class="header-anchor" href="#steg-4-konfigurera-ip-adress" aria-label="Permalink to &quot;Steg 4: Konfigurera IP-adress&quot;">​</a></h3><ol><li>Markera CPU:ns <strong>Ethernet-port</strong> (grönt portikonens)</li><li>Under &quot;Properties&quot; → <strong>Ethernet addresses</strong></li><li>Ställ in IP-adress: <ul><li>Exempel: <code>192.168.0.10</code></li><li>Subnet mask: <code>255.255.255.0</code></li></ul></li><li>Aktivera &quot;Set IP address in the project&quot;</li></ol><h2 id="lagga-till-tillaggsmoduler-sm" tabindex="-1">Lägga till tilläggsmoduler (SM) <a class="header-anchor" href="#lagga-till-tillaggsmoduler-sm" aria-label="Permalink to &quot;Lägga till tilläggsmoduler (SM)&quot;">​</a></h2><p>Om du behöver fler in-/utgångar:</p><ol><li>I hårdvarukatalogen: <strong>Signal modules</strong></li><li>Välj typ: <ul><li><strong>DI</strong> (Digital Input) - För sensorer</li><li><strong>DQ</strong> (Digital Output) - För aktuatorer</li><li><strong>AI</strong> (Analog Input) - För temperatur, tryck, etc.</li><li><strong>AO</strong> (Analog Output) - För styrning 0-10V, 4-20mA</li></ul></li><li>Dra modulen till CPU:ns modulplatser (slot 1, 2, 3...)</li><li>Modulen konfigureras automatiskt</li></ol><h2 id="lagga-till-hmi-panel" tabindex="-1">Lägga till HMI-panel <a class="header-anchor" href="#lagga-till-hmi-panel" aria-label="Permalink to &quot;Lägga till HMI-panel&quot;">​</a></h2><h3 id="steg-1-valj-hmi" tabindex="-1">Steg 1: Välj HMI <a class="header-anchor" href="#steg-1-valj-hmi" aria-label="Permalink to &quot;Steg 1: Välj HMI&quot;">​</a></h3><ol><li>I hårdvarukatalogen: <strong>HMI</strong> → <strong>Comfort Panels</strong></li><li>Välj storlek och typ: <ul><li><strong>KTP700 Basic</strong> - 7&quot; pekskärm, grundläggande</li><li><strong>TP900 Comfort</strong> - 9&quot; pekskärm, avancerad</li><li><strong>MP277</strong> - 10&quot; multitouch</li></ul></li><li>Dra HMI:n till nätverksvyn</li></ol><h3 id="steg-2-anslut-hmi-till-plc" tabindex="-1">Steg 2: Anslut HMI till PLC <a class="header-anchor" href="#steg-2-anslut-hmi-till-plc" aria-label="Permalink to &quot;Steg 2: Anslut HMI till PLC&quot;">​</a></h3><ol><li>Klicka på HMI:ns Ethernet-port</li><li>Dra en linje till PLC:ns Ethernet-port</li><li>En <strong>grön linje</strong> = anslutningen skapas automatiskt</li></ol><h3 id="steg-3-konfigurera-hmi-ip-adress" tabindex="-1">Steg 3: Konfigurera HMI IP-adress <a class="header-anchor" href="#steg-3-konfigurera-hmi-ip-adress" aria-label="Permalink to &quot;Steg 3: Konfigurera HMI IP-adress&quot;">​</a></h3><ol><li>Markera HMI:ns Ethernet-port</li><li>Under &quot;Properties&quot; → <strong>Ethernet addresses</strong></li><li>Ställ in IP i samma subnet som PLC: <ul><li>Exempel: <code>192.168.0.20</code></li><li>Subnet mask: <code>255.255.255.0</code></li></ul></li></ol><h3 id="steg-4-skapa-hmi-anslutning" tabindex="-1">Steg 4: Skapa HMI-anslutning <a class="header-anchor" href="#steg-4-skapa-hmi-anslutning" aria-label="Permalink to &quot;Steg 4: Skapa HMI-anslutning&quot;">​</a></h3><ol><li>Markera HMI:n i projektträdet</li><li>Under <strong>Connections</strong>, dubbelkolla att anslutning till PLC finns</li><li>Om inte: högerklicka &quot;Connections&quot; → &quot;Add new connection&quot;</li></ol><h2 id="lagga-till-frekvensomriktare-via-profinet" tabindex="-1">Lägga till frekvensomriktare via Profinet <a class="header-anchor" href="#lagga-till-frekvensomriktare-via-profinet" aria-label="Permalink to &quot;Lägga till frekvensomriktare via Profinet&quot;">​</a></h2><h3 id="steg-1-installera-gsd-fil" tabindex="-1">Steg 1: Installera GSD-fil <a class="header-anchor" href="#steg-1-installera-gsd-fil" aria-label="Permalink to &quot;Steg 1: Installera GSD-fil&quot;">​</a></h3><p>Frekvensomriktare (t.ex. Sinamics G120) kräver en GSD-fil:</p><ol><li>Ladda ner GSD-filen från Siemens Support Portal</li><li>I TIA Portal: <strong>Options</strong> → <strong>Install general station description file (GSD)</strong></li><li>Välj nedladdad GSD-fil och installera</li></ol><h3 id="steg-2-lagg-till-frekvensomriktare" tabindex="-1">Steg 2: Lägg till frekvensomriktare <a class="header-anchor" href="#steg-2-lagg-till-frekvensomriktare" aria-label="Permalink to &quot;Steg 2: Lägg till frekvensomriktare&quot;">​</a></h3><ol><li>Efter installation finns omriktaren i hårdvarukatalogen: <ul><li><strong>Other field devices</strong> → <strong>PROFINET IO</strong> → <strong>Drives</strong> → <strong>Sinamics</strong></li></ul></li><li>Välj din modell (t.ex. &quot;G120 CU250S-2 PN&quot;)</li><li>Dra till nätverksvyn</li></ol><h3 id="steg-3-anslut-till-profinet" tabindex="-1">Steg 3: Anslut till Profinet <a class="header-anchor" href="#steg-3-anslut-till-profinet" aria-label="Permalink to &quot;Steg 3: Anslut till Profinet&quot;">​</a></h3><ol><li>Dra en linje från frekvensomriktarens port till PLC:ns Profinet-port</li><li>Omriktaren blir automatiskt en Profinet IO-device under PLC:n</li></ol><h3 id="steg-4-konfigurera-enhetsnummer-och-ip" tabindex="-1">Steg 4: Konfigurera enhetsnummer och IP <a class="header-anchor" href="#steg-4-konfigurera-enhetsnummer-och-ip" aria-label="Permalink to &quot;Steg 4: Konfigurera enhetsnummer och IP&quot;">​</a></h3><ol><li>Markera frekvensomriktaren</li><li><strong>Properties</strong> → <strong>Device number</strong>: Ange unik adress (t.ex. 10)</li><li><strong>Properties</strong> → <strong>Ethernet addresses</strong>: Ställ in IP (t.ex. <code>192.168.0.30</code>)</li></ol><h3 id="steg-5-konfigurera-telegramtyp" tabindex="-1">Steg 5: Konfigurera telegramtyp <a class="header-anchor" href="#steg-5-konfigurera-telegramtyp" aria-label="Permalink to &quot;Steg 5: Konfigurera telegramtyp&quot;">​</a></h3><ol><li>Under frekvensomriktaren: <strong>Device configuration</strong></li><li>Välj lämpligt telegram (t.ex. &quot;Standard telegram 1&quot;)</li><li>Detta bestämmer vilka styrord och processdata som överförs</li></ol><h2 id="oversikt-typisk-projektkonfiguration" tabindex="-1">Översikt: Typisk projektkonfiguration <a class="header-anchor" href="#oversikt-typisk-projektkonfiguration" aria-label="Permalink to &quot;Översikt: Typisk projektkonfiguration&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nätverk: 192.168.0.0/24</span></span>
<span class="line"><span>├── PLC (CPU 1214C)        → 192.168.0.10</span></span>
<span class="line"><span>├── HMI (KTP700 Basic)     → 192.168.0.20</span></span>
<span class="line"><span>└── Frekvensomriktare (G120) → 192.168.0.30</span></span></code></pre></div><h2 id="verifiera-hardvarukonfigurationen" tabindex="-1">Verifiera hårdvarukonfigurationen <a class="header-anchor" href="#verifiera-hardvarukonfigurationen" aria-label="Permalink to &quot;Verifiera hårdvarukonfigurationen&quot;">​</a></h2><h3 id="kontrollera-natverksvyn" tabindex="-1">Kontrollera nätverksvyn <a class="header-anchor" href="#kontrollera-natverksvyn" aria-label="Permalink to &quot;Kontrollera nätverksvyn&quot;">​</a></h3><ol><li>Öppna &quot;Devices &amp; networks&quot;</li><li>Alla enheter ska vara <strong>gröna</strong> (inga röda varningar)</li><li>Anslutningar ska visas som <strong>gröna linjer</strong></li></ol><h3 id="kompilera-hardvaran" tabindex="-1">Kompilera hårdvaran <a class="header-anchor" href="#kompilera-hardvaran" aria-label="Permalink to &quot;Kompilera hårdvaran&quot;">​</a></h3><ol><li>Högerklicka på PLC:n</li><li>Välj &quot;Compile&quot; → &quot;Hardware (rebuild all)&quot;</li><li>Kontrollera att inga fel uppstår i &quot;Info&quot; → <strong>Compile</strong>-fliken</li></ol><h2 id="vanliga-problem-och-losningar" tabindex="-1">Vanliga problem och lösningar <a class="header-anchor" href="#vanliga-problem-och-losningar" aria-label="Permalink to &quot;Vanliga problem och lösningar&quot;">​</a></h2><p>❌ <strong>Problem:</strong> &quot;IP address conflict&quot; ✅ <strong>Lösning:</strong> Kontrollera att alla enheter har unika IP-adresser</p><p>❌ <strong>Problem:</strong> &quot;Device not found in catalog&quot; ✅ <strong>Lösning:</strong> Installera GSD-fil för enheten</p><p>❌ <strong>Problem:</strong> &quot;Cannot connect HMI to PLC&quot; ✅ <strong>Lösning:</strong> Kontrollera att båda enheterna är i samma subnet</p><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiella-guider" tabindex="-1">Officiella guider <a class="header-anchor" href="#officiella-guider" aria-label="Permalink to &quot;Officiella guider&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109772804" target="_blank" rel="noreferrer">Adding devices in TIA Portal</a> - Siemens guide</li><li><a href="https://support.industry.siemens.com/cs/document/49948856" target="_blank" rel="noreferrer">Configuring PROFINET</a> - Profinet-konfiguration</li><li><a href="https://support.industry.siemens.com/cs/document/93703241" target="_blank" rel="noreferrer">HMI Connection to PLC</a> - HMI-anslutning</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal add devices tutorial&quot;</li><li>YouTube: &quot;TIA Portal PROFINET configuration&quot;</li><li>YouTube: &quot;TIA Portal HMI connection setup&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Nu när hårdvaran är konfigurerad kan du börja programmera! Se <a href="./../03-konfiguration/plc-hardvara.html">Grundläggande konfiguration</a> för att konfigurera hårdvaruparametrar.</p></div>`,58)])])}const c=a(i,[["render",n]]);export{k as __pageData,c as default};
